import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 500;

const COLORS = {
  bg: "#000000",
  clockFace: "#1a1a1a",
  ringOuter: "#444444",
  ringAccent: "#cccccc",
  hourHand: "#ffffff",
  minuteHand: "#aaaaaa",
  tickMajor: "#888888",
  tickMinor: "#444444",
  numbers: "#cccccc",
  digitalBg: "rgba(255,255,255,0.04)",
  digitalBorder: "rgba(255,255,255,0.15)",
  digitalText: "#dddddd",
  progressArc: "#cccccc",
  progressTrack: "rgba(255,255,255,0.08)",
};

const COUNTING_FRAMES = 375;
const HOLD_FRAMES = 125;

const ClockScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const countingFrame = Math.min(frame, COUNTING_FRAMES);
  const progress = interpolate(countingFrame, [0, COUNTING_FRAMES], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const entranceProgress = spring({
    frame,
    fps,
    delay: 0,
    config: { damping: 180 },
  });

  const clockScale = interpolate(entranceProgress, [0, 1], [0.6, 1]);
  const clockOpacity = interpolate(entranceProgress, [0, 1], [0, 1]);

  const minuteDegrees = interpolate(progress, [0, 1], [0, 120]);
  const hourDegrees = interpolate(progress, [0, 1], [0, 10]);

  const size = 1000;
  const cx = size / 2;
  const cy = size / 2;
  const radius = size / 2 - 20;

  const arcRadius = radius - 28;
  const arcCircumference = 2 * Math.PI * arcRadius;
  const arcProgress = progress * (20 / 60);
  const arcDash = arcCircumference * arcProgress;
  const arcGap = arcCircumference - arcDash;

  const isCounting = frame < COUNTING_FRAMES;

  // Subtle pulse only during counting
  const glowPulse = isCounting
    ? interpolate(
        Math.sin((frame / COUNTING_FRAMES) * Math.PI * 6),
        [-1, 1],
        [0.8, 1]
      )
    : 1;

  // Tick marks
  const ticks = [];
  for (let i = 0; i < 60; i++) {
    const angle = (i * 360) / 60;
    const rad = (angle * Math.PI) / 180;
    const isHour = i % 5 === 0;
    const isQuarter = i % 15 === 0;
    const tickOuter = radius - 6;
    const tickInner = isQuarter
      ? radius - 60
      : isHour
      ? radius - 44
      : radius - 22;

    const x1 = cx + tickOuter * Math.sin(rad);
    const y1 = cy - tickOuter * Math.cos(rad);
    const x2 = cx + tickInner * Math.sin(rad);
    const y2 = cy - tickInner * Math.cos(rad);

    ticks.push(
      <line
        key={i}
        x1={x1}
        y1={y1}
        x2={x2}
        y2={y2}
        stroke={
          isQuarter ? "#ffffff" : isHour ? COLORS.tickMajor : COLORS.tickMinor
        }
        strokeWidth={isQuarter ? 5 : isHour ? 3.5 : 1.5}
        strokeLinecap="round"
        opacity={isQuarter ? 1 : isHour ? 0.7 : 0.35}
      />
    );
  }

  // Hour numbers
  const hourNumbers = [];
  for (let i = 1; i <= 12; i++) {
    const angle = ((i * 360) / 12) * (Math.PI / 180);
    const numRadius = radius - 110;
    const x = cx + numRadius * Math.sin(angle);
    const y = cy - numRadius * Math.cos(angle);
    const isHighlight = i === 12 || i === 3 || i === 6 || i === 9;
    hourNumbers.push(
      <text
        key={i}
        x={x}
        y={y}
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={isHighlight ? 52 : 40}
        fontWeight={isHighlight ? "700" : "400"}
        fill={isHighlight ? "#ffffff" : COLORS.numbers}
        fontFamily="'Inter', sans-serif"
        opacity={isHighlight ? 1 : 0.55}
      >
        {i}
      </text>
    );
  }

  // Hand coords
  const hourRad = (hourDegrees * Math.PI) / 180;
  const hourLength = radius * 0.48;
  const hourTailLength = radius * 0.12;
  const hourX = cx + hourLength * Math.sin(hourRad);
  const hourY = cy - hourLength * Math.cos(hourRad);
  const hourTailX = cx - hourTailLength * Math.sin(hourRad);
  const hourTailY = cy + hourTailLength * Math.cos(hourRad);

  const minuteRad = (minuteDegrees * Math.PI) / 180;
  const minuteLength = radius * 0.72;
  const minuteTailLength = radius * 0.15;
  const minuteX = cx + minuteLength * Math.sin(minuteRad);
  const minuteY = cy - minuteLength * Math.cos(minuteRad);
  const minuteTailX = cx - minuteTailLength * Math.sin(minuteRad);
  const minuteTailY = cy + minuteTailLength * Math.cos(minuteRad);

  // Digital display time — freeze at 20:00
  const totalMinutes = isCounting ? Math.floor(progress * 20) : 20;
  const seconds = isCounting
    ? Math.floor((progress * 20 - totalMinutes) * 60)
    : 0;
  const timeString = `${String(totalMinutes).padStart(2, "0")}:${String(
    seconds
  ).padStart(2, "0")}`;

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "'Inter', sans-serif",
        background: "transparent",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 52,
          opacity: clockOpacity,
          transform: `scale(${clockScale})`,
        }}
      >
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          style={{
            filter: `drop-shadow(0px 20px 60px rgba(0,0,0,0.5))`,
          }}
        >
          <defs>
            <radialGradient id="faceGrad" cx="50%" cy="40%" r="65%">
              <stop offset="0%" stopColor="#2e2e2e" />
              <stop offset="100%" stopColor="#111111" />
            </radialGradient>

            <filter id="handGlow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation="4" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            <filter id="arcGlow" x="-10%" y="-10%" width="120%" height="120%">
              <feGaussianBlur stdDeviation="5" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            <linearGradient id="ringGrad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#555555" />
              <stop offset="50%" stopColor="#aaaaaa" />
              <stop offset="100%" stopColor="#333333" />
            </linearGradient>
          </defs>

          {/* Outer bezel ring */}
          <circle
            cx={cx}
            cy={cy}
            r={radius + 16}
            fill="none"
            stroke="url(#ringGrad)"
            strokeWidth={5}
            opacity={0.7}
          />
          {/* Second bezel ring */}
          <circle
            cx={cx}
            cy={cy}
            r={radius + 6}
            fill="none"
            stroke="rgba(255,255,255,0.06)"
            strokeWidth={2}
          />

          {/* Clock face */}
          <circle cx={cx} cy={cy} r={radius} fill="url(#faceGrad)" />

          {/* Inner subtle rim */}
          <circle
            cx={cx}
            cy={cy}
            r={radius - 2}
            fill="none"
            stroke="rgba(255,255,255,0.08)"
            strokeWidth={2}
          />

          {/* Progress track */}
          <circle
            cx={cx}
            cy={cy}
            r={arcRadius}
            fill="none"
            stroke={COLORS.progressTrack}
            strokeWidth={10}
          />

          {/* Progress arc */}
          <circle
            cx={cx}
            cy={cy}
            r={arcRadius}
            fill="none"
            stroke={COLORS.progressArc}
            strokeWidth={10}
            strokeLinecap="round"
            strokeDasharray={`${arcDash} ${arcGap}`}
            strokeDashoffset={0}
            opacity={isCounting ? 0.75 * glowPulse : 0.75}
            filter="url(#arcGlow)"
            transform={`rotate(-90, ${cx}, ${cy})`}
          />

          {/* Tick marks */}
          {ticks}

          {/* Hour numbers */}
          {hourNumbers}

          {/* Hour hand */}
          <line
            x1={hourTailX}
            y1={hourTailY}
            x2={hourX}
            y2={hourY}
            stroke="#ffffff"
            strokeWidth={18}
            strokeLinecap="round"
            opacity={0.95}
          />

          {/* Minute hand */}
          <line
            x1={minuteTailX}
            y1={minuteTailY}
            x2={minuteX}
            y2={minuteY}
            stroke="#cccccc"
            strokeWidth={9}
            strokeLinecap="round"
            filter="url(#handGlow)"
            opacity={isCounting ? glowPulse : 1}
          />

          {/* Minute hand tip dot */}
          <circle
            cx={minuteX}
            cy={minuteY}
            r={12}
            fill="#ffffff"
            opacity={isCounting ? 0.6 * glowPulse : 0.6}
            filter="url(#handGlow)"
          />

          {/* Center cap */}
          <circle cx={cx} cy={cy} r={30} fill="#1c1c1c" />
          <circle
            cx={cx}
            cy={cy}
            r={30}
            fill="none"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth={3}
          />
          <circle cx={cx} cy={cy} r={14} fill="#aaaaaa" />
          <circle cx={cx} cy={cy} r={6} fill="#ffffff" opacity={0.95} />
        </svg>

        {/* Digital display */}
        <div
          style={{
            background: COLORS.digitalBg,
            border: `2px solid ${COLORS.digitalBorder}`,
            borderRadius: 32,
            padding: "32px 100px",
            fontSize: 100,
            fontWeight: 700,
            color: COLORS.digitalText,
            letterSpacing: "0.18em",
            fontVariantNumeric: "tabular-nums",
            boxShadow: `inset 0 1px 0 rgba(255,255,255,0.05)`,
          }}
        >
          {timeString}
        </div>
      </div>
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={500}>
        <ClockScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
